  [inst : (KFOL.Equational.language (KFOL.Equational.CoreSymbol Role)).Structure M] [Nonempty M],
  have x := KFOL.Equational.coreStructure Role;
  have x_1 := KFOL.Equational.publicStructure Role;
  have x_2 := KFOL.Equational.fullStructure Role;
  have x_3 := KFOL.Envelope.structureOf;
  have x_4 := KFOL.Envelope.publicStructureOf;
  (KFOL.Equational.InVariety (KFOL.Equational.CoreSymbol Role) (KFOL.WinnerSet Role) M ↔
      KFOL.Equational.InVariety (KFOL.Equational.PublicSymbol Role) (KFOL.WinnerSet Role)
        (KFOL.Envelope.Carrier Role M)) ∧
